DECLARE
  l_match_dept       NUMBER;
  l_expected_match   NUMBER;
  l_actual_match     NUMBER;

  l_no_match_dept    NUMBER := -1;
  l_no_match_count   NUMBER;
  l_expected_no_match NUMBER := 0;
  l_actual_no_match  NUMBER;

  l_expected_null    NUMBER := 0;
  l_actual_null      NUMBER;

  l_failures         PLS_INTEGER := 0;

  PROCEDURE check_result(
    p_name     IN VARCHAR2,
    p_expected IN NUMBER,
    p_actual   IN NUMBER
  ) IS
  BEGIN
    IF p_expected = p_actual THEN
      DBMS_OUTPUT.PUT_LINE(
        'PASS: ' || p_name ||
        ' expected=' || p_expected ||
        ' actual=' || p_actual
      );
    ELSE
      DBMS_OUTPUT.PUT_LINE(
        'FAIL: ' || p_name ||
        ' expected=' || p_expected ||
        ' actual=' || p_actual
      );
      l_failures := l_failures + 1;
    END IF;
  END check_result;
BEGIN
  SAVEPOINT test_headcount_sp;

  -- Find a department_id that has at least one employee.
  BEGIN
    SELECT MIN(department_id)
      INTO l_match_dept
      FROM employees
     WHERE department_id IS NOT NULL;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      l_match_dept := NULL;
  END;

  IF l_match_dept IS NULL THEN
    DBMS_OUTPUT.PUT_LINE(
      'FAIL: matching-department setup found no non-NULL department_id in employees'
    );
    l_failures := l_failures + 1;
  ELSE
    BEGIN
      SELECT COUNT(*)
        INTO l_expected_match
        FROM employees
       WHERE department_id = l_match_dept;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        l_expected_match := NULL;
    END;

    IF l_expected_match IS NULL OR l_expected_match = 0 THEN
      DBMS_OUTPUT.PUT_LINE(
        'FAIL: matching-department setup found no employees for department_id=' ||
        l_match_dept
      );
      l_failures := l_failures + 1;
    ELSE
      l_actual_match := harness_app.headcount(l_match_dept);
      check_result(
        p_name     => 'headcount with matching department_id',
        p_expected => l_expected_match,
        p_actual   => l_actual_match
      );
    END IF;
  END IF;

  -- Confirm that the chosen no-match key really matches no row.
  BEGIN
    SELECT COUNT(*)
      INTO l_no_match_count
      FROM employees
     WHERE department_id = l_no_match_dept;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      l_no_match_count := NULL;
  END;

  IF l_no_match_count IS NULL OR l_no_match_count <> 0 THEN
    DBMS_OUTPUT.PUT_LINE(
      'FAIL: no-match setup found rows for department_id=' ||
      l_no_match_dept ||
      '; expected 0 rows'
    );
    l_failures := l_failures + 1;
  ELSE
    l_actual_no_match := harness_app.headcount(l_no_match_dept);
    check_result(
      p_name     => 'headcount with no-match department_id',
      p_expected => l_expected_no_match,
      p_actual   => l_actual_no_match
    );
  END IF;

  -- NULL argument: the function compares with =, so it should match no rows.
  l_actual_null := harness_app.headcount(NULL);
  check_result(
    p_name     => 'headcount with NULL department_id',
    p_expected => l_expected_null,
    p_actual   => l_actual_null
  );

  DBMS_OUTPUT.PUT_LINE('Failure count: ' || l_failures);

  ROLLBACK TO test_headcount_sp;

  IF l_failures <> 0 THEN
    RAISE_APPLICATION_ERROR(
      -20001,
      'headcount test block failed: ' || l_failures || ' check(s) failed'
    );
  END IF;

EXCEPTION
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error: ' || SQLERRM);
    ROLLBACK TO test_headcount_sp;
    RAISE;
END;
```

The block checks three cases. First, it looks for a non-NULL `department_id` in `employees`, computes the expected count independently with a separate `SELECT COUNT(*)`, calls `harness_app.headcount` with that value, and compares the result. If no such department exists, or if the selected department has no employees, the setup check prints `FAIL` and counts as a failure.

Second, it uses `department_id = -1` as a candidate no-match key, confirms independently that no rows match it, then calls `harness_app.headcount(-1)` and expects `0`. If `-1` does match rows, the setup check prints `FAIL` and counts as a failure.

Third, it calls `harness_app.headcount(NULL)`. Because the function uses `department_id = p_department_id`, a NULL argument matches no rows, so the expected result is `0`.

The block starts with a savepoint, rolls back to that savepoint at the end, and also rolls back to it before re-raising any unexpected error. It does not commit. I have not run this block.

